  margin-bottom: 20px;
}
.errors ul { margin: 0; padding-left: 20px; }

/* ---------- Flash ---------- */

.flash {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  z-index: 100;
  background: var(--c-blue);
  color: var(--c-lavender);
  border-radius: 1000px;
  padding: 12px 24px;
  font-weight: 600;
  animation: flash-out 4s forwards;
  pointer-events: none;
}
.flash--alert { background: var(--c-pink); color: var(--c-white); }

@keyframes flash-out {
  0%, 80% { opacity: 1; }
  100% { opacity: 0; visibility: hidden; }
}

