.preview-banner .btn:hover { color: var(--c-lavender); }
.preview-stage { min-height: calc(100vh - 52px); min-height: calc(100dvh - 52px); }
.preview-stage .play { min-height: calc(100vh - 52px); min-height: calc(100dvh - 52px); }
