  .admin-header { padding-top: 16px; padding-bottom: 16px; }
  .admin-header__tag { font-size: 17px; }
  .admin-main { padding-top: 28px; }
  .question-item { grid-template-columns: auto minmax(0, 1fr); gap: 12px; }
  .question-item__actions { grid-column: 1 / -1; align-items: flex-start; flex-direction: row; flex-wrap: wrap; }
  .question-item__actions .buttons { justify-content: flex-start; }
  .question-item__actions .active-toggle-form { margin: 0 4px; }
}

@media (max-width: 540px) {
  .card { padding: 18px; }
  .option-row { grid-template-columns: 1fr; gap: 8px; }
  .option-correct { padding-left: 4px; }
  .preview-banner { align-items: flex-start; flex-direction: column; }
  .preview-stage, .preview-stage .play { min-height: calc(100vh - 76px); min-height: calc(100dvh - 76px); }
}
