cat > app/javascript/controllers/preview_controller.js <<'EOF'
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static values = { questions: Array }
  static targets = [
    "questionPanel", "emptyPanel", "scorePanel", "progress", "questionText",
    "options", "feedback", "nextButton", "score", "restartButton"
  ]

  connect() {
    this.questionIndex = 0
    this.scoreCount = 0
    this.answered = false

    if (this.questionsValue.length === 0) {
      this.questionPanelTarget.hidden = true
      this.scorePanelTarget.hidden = true
      this.emptyPanelTarget.hidden = false
    } else {
      this.showQuestion()
    }
  }

  answer(event) {
    const button = event.target.closest("[data-option-index]")
    if (!button || this.answered || !this.optionsTarget.contains(button)) return

    const question = this.questionsValue[this.questionIndex]
    const selectedIndex = Number(button.dataset.optionIndex)
    const selected = question.options[selectedIndex]
    this.answered = true
    if (selected.correct) this.scoreCount += 1

    this.optionsTarget.classList.add("is-locked", "is-revealed")
    this.optionsTarget.querySelectorAll("[data-option-index]").forEach((optionButton, index) => {
      const option = question.options[index]
      optionButton.disabled = true
      if (optionButton === button) optionButton.classList.add("is-picked")
      if (option.correct) {
        optionButton.classList.add("is-correct")
        optionButton.querySelector(".play-option__mark").textContent = "✓ Correct"
      }
    })

    this.feedbackTarget.textContent = selected.correct ? "Correct!" : "Wrong!"
    this.feedbackTarget.className = `play-status ${selected.correct ? "play-status--right" : "play-status--wrong"}`
    this.feedbackTarget.hidden = false
    this.nextButtonTarget.textContent = this.questionIndex === this.questionsValue.length - 1 ? "See score" : "Next question"
    this.nextButtonTarget.hidden = false
  }

  next() {
    if (!this.answered) return

    if (this.questionIndex === this.questionsValue.length - 1) {
      this.questionPanelTarget.hidden = true
      this.scoreTarget.textContent = `Score: ${this.scoreCount}/${this.questionsValue.length}`
      this.scorePanelTarget.hidden = false
      return
    }

    this.questionIndex += 1
    this.showQuestion()
  }

  restart() {
    this.questionIndex = 0
    this.scoreCount = 0
    this.answered = false

    if (this.questionsValue.length === 0) {
      this.scorePanelTarget.hidden = true
      this.questionPanelTarget.hidden = true
      this.emptyPanelTarget.hidden = false
      return
    }

    this.showQuestion()
  }

  showQuestion() {
    const question = this.questionsValue[this.questionIndex]
    this.emptyPanelTarget.hidden = true
    this.scorePanelTarget.hidden = true
    this.questionPanelTarget.hidden = false
    this.progressTarget.textContent = `Question ${this.questionIndex + 1} of ${this.questionsValue.length}`
    this.questionTextTarget.textContent = question.text
    this.optionsTarget.replaceChildren()
    this.optionsTarget.classList.remove("is-locked", "is-revealed")
    this.feedbackTarget.hidden = true
    this.feedbackTarget.textContent = ""
    this.nextButtonTarget.hidden = true
    this.answered = false

    question.options.forEach((option, index) => {
      const button = document.createElement("button")
      button.type = "button"
      button.className = "play-option"
      button.dataset.optionIndex = index

      const letter = document.createElement("span")
      letter.className = "play-option__letter"
      letter.textContent = String.fromCharCode(65 + (index % 26))

      const title = document.createElement("span")
      title.className = "play-option__title"
      title.textContent = option.text

      const mark = document.createElement("span")
      mark.className = "play-option__mark"
      button.append(letter, title, mark)
      this.optionsTarget.append(button)
    })
  }
}
EOF
