// Add an option row without a round trip; the server still validates and saves it.
document.addEventListener("click", (event) => {
  const button = event.target.closest("[data-add-option]")
  if (!button) return

  const form = button.closest("[data-option-form]")
  const rows = form?.querySelector("[data-option-rows]")
  const template = form?.querySelector("template[data-option-template]")
  if (!rows || !template) return

  const index = rows.querySelectorAll(".option-row").length
  const fragment = document.createElement("template")
  fragment.innerHTML = template.innerHTML
    .replaceAll("__INDEX__", String(index))
    .replaceAll("__NUMBER__", String(index + 1))
  rows.append(fragment.content)
})
EOF
