<div class="preview-banner">
  <span>Previewing <strong><%= @quiz.title %></strong> as a player</span>
  <%= link_to "← Back to quiz", moderate_quiz_path(@quiz), class: "btn btn--light btn--sm" %>
</div>

<%= tag.main(class: "preview-stage", data: { controller: "preview", preview_questions_value: @preview_questions.to_json }) do %>
  <div class="play__top">
    <%= link_to moderate_root_path, class: "logo play__logo", aria: { label: "Quizzy home" } do %>
      <span class="logo__mark">?</span>Quizzy
    <% end %>
    <span><%= @quiz.title %></span>
  </div>

  <section class="play__body play__body--top" data-preview-target="questionPanel">
    <div class="play-question__num" data-preview-target="progress"></div>
