    <div class="play-options" data-preview-target="options" data-action="click->preview#answer"></div>
    <div class="play-status" role="status" aria-live="polite" data-preview-target="feedback" hidden></div>
    <div class="buttons preview-controls">
      <button type="button" class="btn btn--pink" data-preview-target="nextButton" data-action="click->preview#next" hidden></button>
      <button type="button" class="btn btn--ghost" data-preview-target="restartButton" data-action="click->preview#restart">Start over</button>
